package nl.smartstreamlabs.sbwdroneconfig;
import org.junit.jupiter.api.Test;import static org.junit.jupiter.api.Assertions.*;import net.minecraft.core.*;import net.minecraft.world.phys.*;import net.minecraft.world.phys.shapes.*;
class Pb01GeometryTest{
 private boolean blocked(Direction f,AABB nativeBox,int step,int broken){var g=Pb01Geometry.MODEL;var actor=Shapes.create(Pb01Geometry.box(BlockPos.ZERO,f,nativeBox));for(boolean moving:new boolean[]{false,true}){var cs=moving?g.door:g.body;var bases=moving?g.doorBase:g.bodyBase;for(int i=0;i<cs.length;i++){int v=g.variant(moving,bases[i],broken);var p=Pb01Geometry.cell(BlockPos.ZERO,f,cs[i]);if(Shapes.joinIsNotEmpty(actor,g.shape(f,moving,v,step).move(p.getX(),p.getY(),p.getZ()),BooleanOp.AND))return true;}}return false;}
 @Test void normalPlayerCanUseDoorAndInteriorInEveryDirection(){for(var f:Direction.Plane.HORIZONTAL){var doorway=new AABB(1.8,.376,4.45,2.4,2.176,4.95);assertTrue(blocked(f,doorway,0,0),f.toString());assertFalse(blocked(f,doorway,21,0),"Open doorway must pass an ordinary player: "+f);assertFalse(blocked(f,new AABB(-.3,.335,-.3,.3,2.135,.3),0,0),"Interior must remain hollow");assertFalse(blocked(f,new AABB(5.1,.335,4.65,5.4,2.135,4.9),0,0),"Rounded outer corner must not become its bounding cube");}}
 @Test void windowsAreActuallyOpenAndDestroyedDoorAndRoofLoseCollision(){var g=Pb01Geometry.MODEL;assertFalse(Pb01Geometry.intersects(g.zones[1],new Vec3(0,1.85,-6),new Vec3(0,1.85,-3)),"front observation slit");assertTrue(Pb01Geometry.intersects(g.leaf[0],new Vec3(2.1,1.3,7),new Vec3(2.1,1.3,3.5)));assertFalse(Pb01Geometry.intersects(g.leaf[21],new Vec3(2.1,1.3,7),new Vec3(2.1,1.3,3.5)));assertFalse(blocked(Direction.NORTH,new AABB(1.8,.376,4.45,2.4,2.176,4.95),0,1<<10));var roof=new AABB(-.1,4.4,2.9,.1,5,3.1);assertTrue(blocked(Direction.NORTH,roof,0,0));assertFalse(blocked(Direction.NORTH,roof,0,(1<<6)|(1<<8)));}
 @Test void allDamageVariantsRetainOneRootAcrossChunkBoundaries(){var g=Pb01Geometry.MODEL;var root=new BlockPos(15,64,15);for(var f:Direction.Plane.HORIZONTAL)for(boolean moving:new boolean[]{false,true})for(var v:moving?g.doorVariants:g.bodyVariants){var p=Pb01Geometry.cell(root,f,v.cell());assertEquals(root,Ps01Geometry.root(p,f,v.cell()));}assertArrayEquals(new int[]{0,0,0},g.bodyVariants[0].cell());assertEquals(1,g.bodyVariants[0].mask());}
 @Test void originalDoorPivotAndWorldScaleAreAppliedOnce(){var g=Pb01Geometry.MODEL;assertArrayEquals(new double[]{1.46,.34,4.66},g.hinge,1e-7);var a=new org.joml.Vector3f((float)g.hinge[0],(float)g.hinge[1],(float)g.hinge[2]);var b=g.pose(g.names.get("Door_Leaf"),1).transformPosition(new org.joml.Vector3f(a));assertEquals(0,a.distance(b),1e-5);assertEquals(10.9,g.bounds.getXsize(),1e-8);assertEquals(4.82,g.bounds.getYsize(),1e-8);assertEquals(11.15,g.bounds.getZsize(),1e-8);assertEquals(4,g.seats.length);assertEquals(4,g.lamps.length);}
 @Test void everyImportedTriangleAndOriginalResolutionSurvives()throws Exception{var root=java.nio.file.Path.of("src/main/resources/assets/sbwdroneconfig/pb01");try(var in=new java.io.DataInputStream(java.nio.file.Files.newInputStream(root.resolve("pb01.bin")))){assertEquals(0x44454631,in.readInt());int parts=in.readInt(),faces=0;assertEquals(Pb01Geometry.MODEL.parts.size(),parts);for(int i=0;i<parts;i++){int n=in.readInt();faces+=n;in.skipNBytes(n*23L*4);}assertEquals(6002,faces);assertEquals(-1,in.read());}assertEquals(22,Pb01Geometry.MODEL.bones.size());var image=javax.imageio.ImageIO.read(root.resolve("pb01.png").toFile());assertEquals(4096,image.getWidth());assertEquals(2048,image.getHeight());}

 @Test void foundationAndFloorCapsPointOutwardAndUseTheirOwnLighting()throws Exception{var root=java.nio.file.Path.of("src/main/resources/assets/sbwdroneconfig/pb01");int exteriorTop=0,interiorTop=0;try(var in=new java.io.DataInputStream(java.nio.file.Files.newInputStream(root.resolve("pb01.bin")))){in.readInt();int parts=in.readInt();for(int part=0;part<parts;part++){int count=in.readInt();for(int face=0;face<count;face++){float nx=in.readFloat(),ny=in.readFloat(),nz=in.readFloat();float[]v=new float[20];for(int k=0;k<20;k++)v[k]=in.readFloat();if(Pb01Geometry.MODEL.parts.get(part).zone()!=0||Math.abs(ny)<.99f)continue;float y=v[1];int category=Pb01Geometry.MODEL.parts.get(part).category();boolean top=category==1?y>.31f:Math.abs(y-.11f)<.001f||Math.abs(y-.23f)<.001f||Math.abs(y-.3f)<.001f;assertEquals(top?1:-1,ny,.001,"Horizontal foundation face at "+y+" in category "+category);if(top){if(category==0)exteriorTop++;else interiorTop++;}}}}assertTrue(exteriorTop>0,"The exposed slab and steps need lit upward faces");assertTrue(interiorTop>0,"The interior floor retains its own upward surface");}
}
